166		public class DeadKeeperChecker extends AbstractKeeperStateChecker {
167	
168			protected void doCheckShard(String clusterId, ShardMeta shardMeta) {
169				String shardId = shardMeta.getId();
170				List<KeeperMeta> allKeepers = shardMeta.getKeepers();
171				List<KeeperMeta> aliveKeepers = currentMetaManager.getSurviveKeepers(clusterId, shardId);
172				List<KeeperMeta> deadKeepers = getDeadKeepers(allKeepers, aliveKeepers);
173	
174				if (deadKeepers.size() > 0) {
175					logger.info("[doCheck][dead keepers]{}", deadKeepers);
176				}
177				for (KeeperMeta deadKeeper : deadKeepers) {
178					try {
179						keeperStateController.addKeeper(new KeeperTransMeta(clusterId, shardId, deadKeeper));
180					} catch (ResourceAccessException e) {
181						logger.error(String.format("cluster:%s,shard:%s, keeper:%s, error:%s", clusterId, shardId,
182								deadKeeper, e.getMessage()));
183					} catch (Throwable th) {
184						logger.error("[doCheck]", th);
185					}
186				}
187			}
188	
189		}
