	/**
	 * Checks whether the keeper master recorded in the current meta is consistent with the shard's
	 * topology, which tells apart normal operation from an in-progress datacenter migration:
	 * <ul>
	 *     <li>for a primary dc, the keeper master should be one of the shard redises;</li>
	 *     <li>for a backup dc, the keeper master should NOT be a shard redis (it follows the active keeper).</li>
	 * </ul>
	 * When the relationship does not hold, a migration is under way and keeper state must not be corrected.
	 */
	private boolean isCurrentMetaKeeperMasterMatch(String clusterId, String shardId) {
		Pair<String, Integer> keeperMaster = currentMetaManager.getKeeperMaster(clusterId, shardId);
		if (keeperMaster == null) {
			return false;
		}

		boolean keeperMasterIsRedis = isKeeperMasterRedis(clusterId, shardId, keeperMaster);
		if (metaCache.isCurrentDcPrimary(clusterId)) {
			return keeperMasterIsRedis;
		} else {
			return !keeperMasterIsRedis;
		}
	}

	private boolean isKeeperMasterRedis(String clusterId, String shardId, Pair<String, Integer> keeperMaster) {
		List<RedisMeta> redises = metaCache.getShardRedises(clusterId, shardId);
		if (redises == null) {
			return false;
		}
		for (RedisMeta redis : redises) {
			if (ObjectUtils.equals(keeperMaster.getKey(), redis.getIp())
					&& ObjectUtils.equals(keeperMaster.getValue(), redis.getPort())) {
				return true;
			}
		}
		return false;
